create table public.asset_types(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,name text not null check(length(trim(name)) between 2 and 120),active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,name));
create table public.assets(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete restrict,asset_type_id uuid not null references public.asset_types(id) on delete restrict,asset_code text not null check(length(trim(asset_code)) between 2 and 120),status text not null default 'ACTIVE' check(status in('ACTIVE','IN_STOCK','MAINTENANCE','LOST','RETIRED')),identifier text,serial_number text,patrimony_number text,manufacturer text,model text,cost numeric(14,2) check(cost is null or cost>=0),purchase_date date,warranty_ends_at date,supplier_id uuid references public.suppliers(id) on delete set null,location_id uuid references public.customer_locations(id) on delete set null,assigned_collaborator_id uuid references public.collaborators(id) on delete set null,department_unit_id uuid references public.organization_units(id) on delete set null,notes text,extra_fields jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),created_by uuid references public.user_profiles(id) on delete set null,updated_at timestamptz not null default now(),updated_by uuid references public.user_profiles(id) on delete set null,unique(organization_id,asset_code));
create table public.asset_history(id uuid primary key default gen_random_uuid(),asset_id uuid not null references public.assets(id) on delete restrict,organization_id uuid not null references public.organizations(id) on delete restrict,event_type text not null check(event_type in('CREATED','UPDATED','ASSIGNED','UNASSIGNED','INVENTORIED','STATUS_CHANGED')),before_value jsonb,after_value jsonb,created_at timestamptz not null default now(),actor_id uuid references public.user_profiles(id) on delete set null);
create trigger assets_updated before update on public.assets for each row execute function public.set_updated_at();
create index assets_org_status_idx on public.assets(organization_id,status,asset_type_id); create index asset_history_asset_idx on public.asset_history(asset_id,created_at desc);
alter table public.asset_types enable row level security; alter table public.assets enable row level security; alter table public.asset_history enable row level security;
create policy "members read asset types" on public.asset_types for select to authenticated using(public.is_organization_member(organization_id)); create policy "members read assets" on public.assets for select to authenticated using(public.is_organization_member(organization_id)); create policy "members read asset history" on public.asset_history for select to authenticated using(public.is_organization_member(organization_id));
create policy "managers manage asset types" on public.asset_types for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
create policy "managers manage assets" on public.assets for all to authenticated using(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[])) with check(public.has_organization_role(organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]));
